const fs = require('fs');

function main() {
  const lines = fs
    .readFileSync(0, 'utf8')
    .split('\n')
    .map((s) => s.replace(/\r/g, ''))
    .filter((s) => s.trim().length > 0);

  let idx = 0;
  const header = lines[idx++].trim().split(/\s+/);
  const n = +header[0];
  const m = +header[1];

  const grid = new Array(n);
  for (let i = 0; i < n; i++) {
    let line = lines[idx++] || '';
    if (line.length < m) line += '.'.repeat(m - line.length);
    grid[i] = line;
  }

  const total = n * m;
  const wet = new Uint8Array(total);
  const queue = new Int32Array(total);
  let head = 0;
  let tail = 0;

  // ponto de vazamento (único 'o' na primeira linha)
  const start = grid[0].indexOf('o');
  if (start >= 0) {
    wet[start] = 1;
    queue[tail++] = start;
  }

  // Propagação (fechamento mínimo das regras do enunciado):
  // - célula molhada com '.' embaixo -> molha a de baixo (queda vertical)
  // - célula molhada com '#' embaixo -> escorre para esquerda/direita
  //   (molha as laterais que sejam '.'; nelas a água continua ou cai)
  while (head < tail) {
    const pos = queue[head++];
    const i = (pos / m) | 0;
    const j = pos - i * m;

    if (i + 1 >= n) continue; // última linha
    const below = grid[i + 1][j];

    if (below === '.') {
      const np = pos + m;
      if (!wet[np]) {
        wet[np] = 1;
        queue[tail++] = np;
      }
    } else if (below === '#') {
      if (j + 1 < m && grid[i][j + 1] === '.') {
        const np = pos + 1;
        if (!wet[np]) {
          wet[np] = 1;
          queue[tail++] = np;
        }
      }
      if (j - 1 >= 0 && grid[i][j - 1] === '.') {
        const np = pos - 1;
        if (!wet[np]) {
          wet[np] = 1;
          queue[tail++] = np;
        }
      }
    }
  }

  const out = new Array(n);
  for (let i = 0; i < n; i++) {
    const row = grid[i];
    const base = i * m;
    const chars = new Array(m);
    for (let j = 0; j < m; j++) {
      chars[j] = wet[base + j] ? 'o' : row[j];
    }
    out[i] = chars.join('');
  }

  process.stdout.write(out.join('\n') + '\n');
}

main();
